using BenchmarkDotNet.Attributes;

// 1. PROFILE: dotnet-trace collect, or PerfView; find the hot method AND the
//    allocation sites (dotnet-counters) - in .NET allocation is often the cost.
//
// 3. ONE CHANGE at the measured hotspot. The usual .NET wins:
//    - avoid LINQ in a hot loop (each stage allocates an iterator)
//    - foreach over a List<T> of structs, not IEnumerable<T> (no boxing)
//    - a struct for a small value type (stays on the stack)
//    - make the call site monomorphic (the JIT inlines only then)
[MemoryDiagnoser]                     // shows allocations per operation
[SimpleJob(RuntimeMoniker.Net90)]
public class SumBench
{
    [Benchmark(Baseline = true)]
    public long Linq()   => items.Where(i => i > 0).Sum();      // allocates

    [Benchmark]
    public long Loop()   // no allocation; the JIT inlines this at a monomorphic site
    { long s = 0; for (int i = 0; i < items.Count; i++) s += items[i]; return s; }

    private readonly List<int> items = new(1 << 16);
}
/* 4. VERIFY with BenchmarkDotNet: it reports the error and the allocation
 *    per operation, so a 2% 'win' inside the noise is visible.
 * 5. GUARD: keep it as a benchmark job in CI.
 * TRAP: tiered compilation means the first ~30 calls run UNOPTIMISED - a
 *    benchmark without warm-up measures the slow tier. */
